<script setup lang="ts">

import type {Row} from "../../types/EditorTypes";
import ContainerBox from "./containerBox.vue";

function mergeStyles(style1:any, style2:any) {
  return {...style1, ...style2};
}
const props = defineProps<{
  rows: Row[],
  form:any
}>()
const localRows = ref(JSON.parse(JSON.stringify(props.rows)));
watch(() => props.rows, (newRows) => {
  localRows.value = JSON.parse(JSON.stringify(newRows));
}, { deep: true });
const rules = {
  required:
    [
      (value: string) => {
        if (value) return true
        return 'This field is required'
      },
    ],
  requiredNumber:
    [
      (value: string) => {
        if (/^\d+$/.test(value.toString())) return true
        return 'This field must be a number'
      },
    ]
}
function getRule(rule:'requiredNumber'|'required'|''){
  switch(rule){
    case 'requiredNumber':
      return rules.requiredNumber
    case 'required':
      return rules.required
    default:
      return undefined
  }
}

const config = useRuntimeConfig()
const loading = ref(false)
const show = ref(false)
const message = ref('Saved successfully!')
const color = ref('success')

async function submit(){
  loading.value = true
  const fd = new FormData();
  fd.append("formName", props.form.title)

  // Use localRows here!
  localRows.value.forEach((r: any) => {
    r.columns.forEach((col: any) => {
      col.elements.forEach((elm: any) => {
        if(elm.data.name){
          fd.append(elm.data.name, elm.data.model)
        }
      })
    })
  })
  try {
    const res = await $fetch('api/forms/result/store', {
      method: 'POST',
      baseURL:config.public.baseUrl,
      body: fd
    })

    console.log(res)
  } catch (err) {
    console.error(err)
  } finally {
    message.value = 'Form submitted!'
    color.value = 'success'
    show.value = true
    loading.value = false
  }
}
</script>

<template>
  <v-container fluid style="display:flex;flex-direction: column;gap: 10px">
    <v-snackbar
        style="z-index: 9999999"
        v-model="show"
        :color="color"
        timeout="3000"
        location="top right"
    >
      {{ message }}
    </v-snackbar>
    <template v-for="row in localRows">
      <container-box
          is-normal-in-fluid
        :style="mergeStyles(mergeStyles(row.margin,row.padding),{background:row.background_type==='color' ?  row.background : `url(${config.public.baseUrl}/${row.background})`,position:'relative',backgroundPosition:'center center'})">
        <v-col v-for="column in row.columns" :key="row.id.toString()+column.id.toString()+'column'"
               style="position: relative;padding: 0" cols="12" sm="12"
               :md="column.column_md" :lg="column.column_lg" :xl="column.column_xl">
          <div style="width: 100% ; height:100%" :style="mergeStyles(column.styles,column.padding)">
            <template v-for="element in column.elements">
              <div style="width: 100% ; position: relative" :style="element.padding">
                <v-text-field v-if="element.element_key==='simpleInput'"  :variant="element.data.variant" :placeholder="element.data.placeholder" :label="element.data.label" :rules="getRule(element.data.errorRule)" v-model="element.data.model"></v-text-field>
                <v-textarea v-if="element.element_key==='textareaInput'" :variant="element.data.variant" :placeholder="element.data.placeholder" :label="element.data.label" :rules="getRule(element.data.errorRule)" v-model="element.data.model"></v-textarea>
                <v-col v-if="element.element_key==='formButton'"
                       :style="mergeStyles(element.padding,{display: 'flex', flexDirection: 'row', justifyContent: element.data.align})">
                  <v-btn v-if="element.data.buttonTitle!==''" :loading="loading" @click="submit" :icon="element.data.icon"

                         :size="element.data.icon?'small':undefined" :to="element.data.buttonLink"
                         :variant="element.data.ButtonsStyles.style" :block="element.data.datafullWidth"
                         :color="element.data.buttonColor"
                         :rounded="element.data.ButtonsStyles.rounded ? element.data.ButtonsStyles.rounded : '8px'">
                    <template #prepend>
                      <v-icon v-if="element.data.buttonIcon!==''">{{ element.data.buttonIcon }}</v-icon>
                    </template>
                    <template v-if="!!element.data.icon"><v-icon v-if="element.data.buttonIcon!==''">{{ element.data.buttonIcon }}</v-icon></template>
                    <template v-if="!element.data.icon"><span style="padding-top: 2px">{{ element.data.buttonTitle }}</span></template>
                  </v-btn>
                </v-col>
              </div>
            </template>
          </div>
        </v-col>
      </container-box>
    </template>
  </v-container>
</template>

